                  setLiveEvents(prev => [...prev, { id: `le-${Date.now()}`, time: new Date().toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' }), type: 'step', message: 'File delivery approved and sent', device: 'System', icon: '📤' }]);
